pages = {}
def page(slug,title,description,content):
    canonical = SITE + ('/' if slug=='index' else f'/{slug}.html')
    schema = {'@context':'https://schema.org','@type':'Organization','name':'Dayspring Centre Limited','url':SITE,'telephone':'+447519560119','areaServed':'England','address':{'@type':'PostalAddress','streetAddress':'2 Athena Apartment, Jubilee Way','addressLocality':'Sidcup','postalCode':'DA14 4BL','addressCountry':'GB'}}
    html=f'''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Dayspring Centre</title><meta name="description" content="{escape(description,quote=True)}"><meta name="theme-color" content="#164e4a"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:locale" content="en_GB"><meta property="og:title" content="{escape(title,quote=True)} | Dayspring Centre"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{SITE}/assets/children-play-hero.jpg"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/dayspring-centre-icon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="/assets/style.css?v={CSS_VERSION}"><script type="application/ld+json">{json.dumps(schema)}</script><script src="/assets/app.js?v={JS_VERSION}" defer></script></head><body>{header(slug)}<main id="main">{content}</main>{footer()}</body></html>'''
    html=html.replace('<h3>Here to help</h3>', '<h3>Here to help</h3><a class="email-link" href="mailto:dayspringcentre@dayspringcentre.co.uk">dayspringcentre@<wbr>dayspringcentre.co.uk</a>')
    html=html.replace('This planner creates a summary on your device. It does not send an enquiry. Call us to start a conversation and arrange how to share further information safely.', 'Prepare a general enquiry, then open it in your email app to review and send to dayspringcentre@dayspringcentre.co.uk. This website does not send it automatically. For detailed referrals or CVs, contact us to agree a suitable route.')
    html=html.replace('I understand this summary stays on my device and is not submitted to Dayspring Centre.', 'I understand I need to review and send the enquiry from my email app; this website does not submit it automatically.')
    html=html.replace('Create my conversation summary', 'Prepare my enquiry')
    html=html.replace('They do not submit an enquiry to Dayspring Centre or store form contents in browser storage.', 'They do not submit an enquiry to Dayspring Centre or store form contents in browser storage. If you choose “Open email draft”, the summary is passed to your email application so you can review and send it. Sending it shares the details with Dayspring Centre at dayspringcentre@dayspringcentre.co.uk.')
    html=html.replace('<h2>We’re ready to listen.</h2>', '<h2>We’re ready to listen.</h2><p>Email <a class="email-link" href="mailto:dayspringcentre@dayspringcentre.co.uk">dayspringcentre@dayspringcentre.co.uk</a> or call us to discuss your enquiry.</p>')
    (ROOT/f'{slug}.html').write_text(html,encoding='utf-8')
    pages[slug] = title

def pagehero(eyebrow,title,lead,action='Talk to us',href='/contact.html'):
    secondary = button('Explore services','/services.html','outline') if href.startswith('tel:') else button('Call '+PHONE,'tel:+447519560119','outline')
    return f'<div class="wrap breadcrumb"><a href="/">Home</a> <span aria-hidden="true">/</span> {eyebrow}</div><section class="page-hero"><div class="wrap"><span class="eyebrow">{eyebrow}</span><h1>{title}</h1><p class="lead">{lead}</p>'+ (f'<div class="hero-actions">{button(action,href)}{secondary}</div>' if action else '')+'</div></section>'
def layout(content,sidebar=True):
    side=f'<aside class="sidebar"><span class="eyebrow">A good place to start</span><h3>Let’s find the right support.</h3><p>Tell us a little about your situation. We’ll listen, answer your questions and explain the next steps.</p>{button("Get in touch","/contact.html")}<a class="phone" href="tel:+447519560119">{PHONE}</a><small>Supporting England. Availability is confirmed after an initial discussion.</small></aside>' if sidebar else ''
    return f'<section class="section"><div class="wrap page-layout"><div class="prose">{content}</div>{side}</div></section>'
def ul(items): return '<ul class="support-list">'+''.join(f'<li>{s}</li>' for s in items)+'</ul>'
def smallcards(items): return '<div class="cards-small">'+''.join(f'<div class="small-card"><h3>{t}</h3><p>{p}</p></div>' for t,p in items)+'</div>'
def servicecards(items):
    return ''.join(f'<article class="service-card"><span class="card-number">0{services.index(s)+1}</span><div class="service-icon">{icon(s[4])}</div><h3>{s[1]}</h3><p>{s[3]}</p>{link("Explore "+("consultancy" if s[0]=="consultancy" else "support"),"/"+s[0]+".html")}</article>' for s in items)

faq=[('What support is right for me or my family?','Start with a conversation. We will listen to what is working well, where you would like help and what you hope to achieve. Together, we can explore whether our services are the right fit.'),('Which areas do you cover?','We are based in Sidcup and support communities across England. Availability, travel and the type of support needed are discussed before any service is agreed.'),('Can I make a referral for someone else?','Families and professionals can contact us to discuss a referral. Please make sure you have an appropriate basis for sharing someone’s information. Start with a general enquiry; we will explain how to share detailed information safely.'),('Is your childcare registered with Ofsted?','Our childcare provision is registered with Ofsted under registration number EY552018, as set out in our service information. This relates to childcare provision and should not be read as a registration or rating for our other services.'),('How much does support cost?','Costs depend on the support needed, its frequency and location. We discuss the options and provide an individual quotation before you decide. Please call us to talk through your needs and any funding arrangements.')]
